def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    weights = 1.0 / (1.0 + np.arange(len(bins), dtype=float))
    scores = np.where(valid, - (remaining + 1e-5) / weights, -np.inf)
    return scores

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target = 0.1 * bins.max() if len(bins) > 0 else 0.1
    return np.where(remaining >= 0, -np.abs(remaining - target), -np.inf)
